from math import factorial,prod
from .authoring import maker,finish
from .common import section
q=maker('congruence-systems',['modular inverses','compatible congruences','cycles'])
p=[
q(1,r'Find the least positive integer x satisfying $7x\equiv5\pmod{26}$.',23,[(15,'Report the inverse rather than the solution.'),(5,'Cancel the coefficient without an inverse.'),(19,'Use an inverse modulo a different modulus.'),(7,'Interchange the coefficient and target.')],[r'The inverse of 7 modulo 26 is 15 because 7·15=105≡1.',r'Multiply the entire congruence by 15: x≡75≡23.',r'The least positive representative is 23; 7·23-5=156 is divisible by 26.'],['Find a multiplier that turns seven into one modulo 26.','Apply it to both sides.'],'Use an inverse only when the coefficient is coprime to the modulus.',lambda:next(x for x in range(1,27) if (7*x-5)%26==0),level=2),
q(2,r'How many integers $1\le x\le20$ satisfy $6x\equiv8\pmod{14}$?',3,[(1,'Treat the least residue as the only solution.'),(2,'Exclude the upper endpoint.'),(6,'Keep the original modulus after canceling and duplicate solutions.'),(0,'Assume a noninvertible coefficient makes every congruence impossible.')],[r'Divide the integer divisibility statement 14|(6x-8) by 2: 7|(3x-4).',r'Now x≡6 modulo 7, because 3·6≡4.',r'The interval contains x=6,13,20, giving three solutions.'],['The coefficient has no inverse modulo fourteen.','Divide the coefficient, target, and modulus by their common factor first.'],'Handle cancellation in a noncoprime congruence.',lambda:sum((6*x-8)%14==0 for x in range(1,21))),
q(3,r'Find the least positive n with remainders 2,3,4 on division by 5,7,9 respectively.',157,[(17,'Satisfy only the first two conditions.'),(67,'Satisfy only the first and third conditions.'),(472,'Use the next representative rather than the least.'),(52,'Combine remainder values without their moduli.')],[r'The first two conditions give n=17+35k.',r'Modulo 9, 8+8k≡4, so k≡4 modulo 9.',r'The least positive value is 17+35·4=157; all solutions differ by 315.'],['Combine two conditions first.','Substitute the resulting progression into the third condition.'],'Solve simultaneous congruences sequentially.',lambda:next(n for n in range(1,316) if n%5==2 and n%7==3 and n%9==4)),
q(4,r'What is the least positive n with $n\equiv3\pmod8$ and $n\equiv7\pmod{12}$?',19,[(7,'Check only the second condition.'),(11,'Check only the first condition.'),(43,'Use the next representative.'),(0,'Assume noncoprime moduli always make the system inconsistent.')],[r'The residues agree modulo gcd(8,12)=4, so there is no compatibility obstruction.',r'Write n=3+8k. Then 8k≡4 modulo 12, giving k≡2 modulo 3.',r'Thus n≡19 modulo lcm(8,12)=24, and the least positive value is 19.'],['Check the residues modulo the common divisor.','The final period is the least common multiple.'],'Distinguish compatible noncoprime systems from impossible ones.',lambda:next(n for n in range(1,25) if n%8==3 and n%12==7)),
q(5,r'How many integers $1\le n\le1000$ satisfy $n^2\equiv1\pmod{24}$?',333,[(500,'Require only that n be odd.'),(667,'Require only that n not be divisible by three.'),(334,'Miscount the final incomplete block.'),(167,'Retain only one of the two residue classes modulo six.')],[r'An odd square is 1 modulo 8. A square is 1 modulo 3 exactly when its base is not divisible by 3.',r'Thus the condition is equivalent to n≡1 or 5 modulo 6.',r'There are 166 full blocks of six, giving 332 values, and the final block 997–1000 adds 997 only. The total is 333.'],['Split 24 into coprime factors 8 and 3.','Characterize which integers satisfy both smaller square conditions.'],'Turn a square congruence into an exact residue count.',lambda:sum((n*n-1)%24==0 for n in range(1,1001))),
q(6,r'What is the units digit of $7^{7^7}$?',3,[(7,'Reduce the exponent modulo ten instead of four.'),(9,'Use an even exponent residue.'),(1,'Assume the exponent is divisible by the cycle length.'),(0,'Confuse the last digit of a power with multiplication by ten.')],[r'Powers of 7 have units digits 7,9,3,1 with period four.',r'The exponent satisfies $7^7\equiv(-1)^7\equiv3\pmod4$.',r'The third position of the cycle is 3.'],['Find the units-digit period before simplifying the exponent.','Reduce the exponent modulo that period.'],'Use one modular cycle inside another.',lambda:pow(7,7**7,10),level=2),
q(7,r'What is the remainder when $3^{100}$ is divided by 13?',3,[(1,'Forget the exponent remainder after grouping in threes.'),(9,'Use exponent remainder two.'),(10,'Reduce the exponent modulo thirteen.'),(12,'Assume the final nonzero residue is minus one.')],[r'$3^3=27\equiv1\pmod{13}$.',r'Since 100=3·33+1, $3^{100}\equiv(3^3)^{33}3\equiv3$.',r'This explicitly verified period is sufficient; no general exponent theorem is needed.'],['Check a few small powers for a residue of one.','Divide the exponent by the resulting period.'],'Use a verified short multiplicative cycle.',lambda:pow(3,100,13),level=2),
q(8,r'A decimal integer consists of 100 consecutive digits, each equal to 1. What is its remainder modulo 27?',19,[(1,'Reduce each power of ten to one modulo twenty-seven.'),(10,'Count digits modulo nine only.'),(9,'Keep only the linear binomial correction.'),(0,'Assume every multiple-of-ten digit count is divisible by twenty-seven.')],[r'The number is $\sum_{k=0}^{99}10^k$. Since 10=1+9, the binomial expansion gives $10^k\equiv1+9k\pmod{27}$.',r'Summing yields $100+9(99\cdot100/2)=44650$.',r'The remainder is 19. Terms involving 9² vanish modulo 27, which justifies the truncation.'],['Write the decimal number as a sum of powers.','Expand ten as one plus a multiple of nine.'],'Truncate a binomial expansion using modular divisibility.',lambda:int('1'*100)%27),
q(9,r'The integer N is defined by $N=2520(1+1/2+\cdots+1/10)$. What is the remainder of N modulo 7?',3,[(0,'Cancel seven from every denominator indiscriminately.'),(1,'Retain only the denominator rather than its complementary factor.'),(6,'Use 2520/6 as the surviving term.'),(4,'Lose the sign in reducing the surviving quotient.')],[r'Every quotient 2520/k is an integer because 2520 is a common multiple of 1 through 10.',r'For k≠7 the quotient remains divisible by 7; only k=7 removes its sole factor of seven.',r'Thus N≡2520/7=360≡3 modulo 7.'],['Determine which terms remain divisible by seven after division.','Only a denominator containing seven can remove that factor.'],'Find the unique term surviving modular cancellation.',lambda:sum(2520//k for k in range(1,11))%7),
q(10,r'How many nine-digit integers using each digit 1 through 9 exactly once are divisible by 36?',80640,[(40320,'Miss half of the valid final digit pairs.'),(362880,'Use only the divisibility-by-nine test.'),(181440,'Require only an even final digit.'),(161280,'Double-count the order of each final pair.')],[r'The digit sum is 45, so every arrangement is divisible by 9. Divisibility by 36 therefore reduces to divisibility by 4.',r'The eligible two-digit endings are 12,16,24,28,32,36,48,52,56,64,68,72,76,84,92,96: sixteen in all.',r'Each leaves seven distinct digits in any order, giving $16\cdot7!=80640$.'],['Separate divisibility by nine from divisibility by four.','Count admissible final pairs before arranging the other digits.'],'Combine a digit invariant with a local divisibility condition.',lambda:sum(n%4==0 and '0' not in str(n) and len(set(str(n)))==2 for n in range(10,100))*factorial(7)),
q(11,r'For how many integers $1\le n\le10$ is $n!+1$ divisible by 11?',2,[(1,'Assume Wilson’s theorem gives the only solution.'),(10,'Apply Wilson’s theorem at every factorial index.'),(3,'Include a residue of positive one as well as minus one.'),(0,'Mistake n<11 for a prohibition on divisibility.')],[r'Compute successive factorial residues modulo 11: 1,2,6,2,10,5,2,5,1,10.',r'The desired residue is -1≡10, occurring at n=5 and n=10.',r'Wilson’s theorem guarantees the latter for the prime 11 but does not exclude the former. There are two solutions.'],['Track factorial residues by multiplying the preceding residue by the next index.','A theorem guaranteeing one solution need not establish uniqueness.'],'Avoid inferring a converse from a sufficient modular theorem.',lambda:sum((factorial(n)+1)%11==0 for n in range(1,11))),
q(12,r'How many integers $1\le n\le1000$ have a square ending in the digits 44?',40,[(20,'Retain only the two roots modulo twenty-five.'),(10,'Retain a single residue class modulo one hundred.'),(80,'Count both signs twice after lifting.'),(0,'Assume a square cannot end in two repeated digits.')],[r'The condition is n²≡44 modulo 100. Modulo 25, n²≡19, whose roots are 12 and 13 modulo 25, checked among residues 0 through 24.',r'Modulo 4, n must be even. Combining parity with the four lifts of each residue gives n≡12,38,62,88 modulo 100.',r'Each of the ten complete blocks of 100 has four solutions, for a total of 40.'],['Solve the condition modulo twenty-five and modulo four.','Lift only roots with the required parity.'],'Combine local square roots and count their lifts.',lambda:sum(n*n%100==44 for n in range(1,1001))),
q(13,r'How many integers $1\le n\le100$ satisfy $n^3\equiv n\pmod6$?',100,[(50,'Check only parity.'),(66,'Exclude multiples of three unnecessarily.'),(33,'Require n itself to be divisible by six.'),(0,'Assume a cubic cannot have the same residue as its base.')],[r'$n^3-n=(n-1)n(n+1)$ is a product of three consecutive integers.',r'It contains a multiple of 3 and at least one even factor, so it is divisible by 6.',r'Every one of the 100 integers qualifies.'],['Factor the difference rather than computing a hundred cubes.','Use the divisibility properties of consecutive integers.'],'Prove a congruence uniformly by factorization.',lambda:sum((n**3-n)%6==0 for n in range(1,101)),level=2),
q(14,r'What are the last two digits of $3^{3^3}$, interpreted as an integer from 0 to 99?',87,[(27,'Evaluate only the exponent.'),(83,'Reverse the final digits.'),(7,'Use a units-digit cycle for a two-digit question.'),(1,'Assume the exponent is a multiple of the period.')],[r'The exponent is 27. Since $3^{20}\equiv1\pmod{100}$, it suffices to compute $3^7$.',r'The period statement follows from $3^{10}=59049\equiv49$ and $49^2\equiv1$ modulo 100.',r'$3^7=2187$, whose last two digits are 87.'],['The modulus must be one hundred, not ten.','Verify a power congruent to one, then reduce the exponent.'],'Choose the modulus and prove the exponent reduction.',lambda:pow(3,3**3,100),level=2)]
e=[
q(101,r'Find the least positive integer n with $n\equiv2\pmod7$ and $n\equiv5\pmod9$.',23,[(5,'Ignore the first congruence.'),(16,'Use an incorrect residue for the substitution variable.'),(86,'Use the next solution.'),(63,'Report the period instead of a representative.')],[r'Encode the first condition exactly as n=2+7k. This prevents us from losing it while solving the second.',r'The second condition becomes 7k≡3 modulo 9. Multiplication by 4, the inverse of 7, gives k≡3.',r'Hence n=23+63t. The least positive representative is 23, and both original remainders check.',r'The product 63 is the period because 7 and 9 are coprime. For noncoprime moduli, compatibility and the least common multiple must replace this shortcut.'],['Express all numbers satisfying the first condition.','Substitute into the second and solve for the new integer parameter.'],'Solve and verify a two-modulus system.',lambda:next(n for n in range(1,64) if n%7==2 and n%9==5),level=2),
q(102,r'How many residues $x\in\{0,1,\ldots,17\}$ solve $6x\equiv12\pmod{18}$?',6,[(1,'Divide coefficients but keep modulus eighteen.'),(3,'Use the reduced modulus as the count.'),(2,'Count just the least positive roots.'),(0,'Assume the coefficient must have an inverse.')],[r'The congruence says 18 divides 6x-12. Dividing the integer divisibility statement by 6 gives 3 divides x-2.',r'Thus x≡2 modulo 3, not modulo 18. The residues are 2,5,8,11,14,17.',r'There are six solutions. Checking each in the original congruence confirms that canceling must also change the modulus.',r'The general condition for ax≡b modulo m to be solvable is gcd(a,m)|b; when solvable, there are gcd(a,m) distinct residues modulo m.'],['Translate the congruence into divisibility before canceling.','After cancellation, identify the new period.'],'Explain noninvertible modular cancellation.',lambda:sum((6*x-12)%18==0 for x in range(18)))]
finish('congruence-systems','Congruences: inverses, cycles & compatibility','Number theory','modular divisibility integer-constraints',24,'291–305',
 [r'Modular arithmetic is a way to retain exactly the information a problem asks for. The crucial choices are the modulus, the period, and which terms survive reduction. Large exponents alone do not make a problem difficult; choosing and justifying the right reduction does.',r'This study moves from one congruence to systems, digit constraints, and modular cancellation in a rational sum. Before dividing anything, decide whether you are using an inverse or changing the underlying divisibility statement.'],
 [section('Cancellation needs a reason',r'If gcd(a,m)=1, an inverse of a exists modulo m, and multiplying by it legitimately cancels a. If the gcd is larger, an inverse does not exist. Translate ax≡b into m|(ax-b). A common divisor d of a and m must divide b; otherwise the congruence is impossible.',r'When d divides b, divide all three quantities by d. The resulting modulus is m/d. Solutions in the reduced modulus can lift to several residues in the original modulus. Keeping m after dividing a and b discards valid solutions, as the second worked example demonstrates.',r'A rational expression modulo m is not automatically meaningful. In an integer sum made by multiplying fractions by a common denominator, analyze each resulting integer term. A denominator divisible by a chosen prime can remove that prime from one term while every other term vanishes modulo the prime.'),
 section('Combine conditions without assuming coprimality',r'For two coprime moduli, write the first congruence as an arithmetic progression and substitute it into the second. The resulting solution repeats modulo the product. This constructive procedure explains the Chinese remainder theorem in the two-modulus case and makes the least-positive requirement easy to check.',r'If the moduli share a gcd d, the prescribed residues must agree modulo d. Compatible systems repeat modulo the least common multiple, not necessarily the product. Incompatible systems have no solution. Test compatibility before searching through a long list of candidates.',r'Composite square congruences may have more than two roots. Solve modulo convenient prime powers and combine the results, preserving every valid lift. A root modulo 25 is a necessary condition for a square ending in specified digits, but its parity must also fit the condition modulo four.'),
 section('Reduce powers and digits structurally',r'An exponent is reduced modulo a proven multiplicative period, not automatically modulo the modulus itself. Fermat’s theorem states that a prime p and a base coprime to p imply a^(p-1)≡1 modulo p. It is not a converse primality test. Sometimes checking three small powers reveals a shorter period and is all the theorem you need.',r'For decimal blocks, express the integer as a sum of powers of ten. If ten is close to one modulo a useful divisor, a binomial expansion may truncate because its higher terms contain enough prime factors to vanish. State exactly why those terms vanish before using the shortened expression.',r'Digit arrangements connect modular arithmetic to counting. A digit sum may make divisibility by nine automatic, while divisibility by four depends only on the final two digits. Count the eligible endings, then arrange what remains. This separation works only when all counted arrangements satisfy both conditions and no arrangement is counted twice.')],
 ['Distinguish invertible cancellation from modulus reduction.','Solve compatible systems and count every residue representative.','Use cycles, digit structure, and surviving terms to simplify large expressions.'],
 [r'Write ax≡b as m|(ax-b) before dividing by a common factor.',r'Write n=a+mk and substitute into the other congruence.',r'Prove a^T≡1, then write the exponent as qT+r and reduce.'],
 'A congruence theorem may provide a sufficient condition without a converse. Check hypotheses and avoid turning one guaranteed solution into a uniqueness claim.',e,p,
 dict(prompt=r'Solve $8x\equiv12\pmod{20}$ and list the solutions in $0\le x<20$.',answer=r'$x=4,9,14,19$.',steps=[r'Divide the divisibility relation by four to get 2x≡3 modulo 5.',r'The inverse of two modulo five is three, so x≡4 modulo 5; list all four representatives.']),
 ['modular inverses','noncoprime cancellation','Chinese remainder construction','prime-power digit tests'],
 [(r'ax\equiv b\pmod m\iff x\equiv a^{-1}b\pmod m','Inverse cancellation','solving a linear congruence without changing its modulus','$\\gcd(a,m)=1$.'),(r'ax\equiv b\pmod m\iff (a/d)x\equiv b/d\pmod{m/d}','Common-factor reduction','reducing a linear congruence with a noninvertible coefficient','$d$ divides $a,b,m$; solvability requires $\\gcd(a,m)$ to divide $b$.'),(r'a^{p-1}\equiv1\pmod p','Fermat exponent reduction','reducing powers modulo a prime','p is prime and p does not divide a; the converse primality claim is false.'),(r'x\equiv a\pmod m,\ x\equiv b\pmod n\Rightarrow a\equiv b\pmod{\gcd(m,n)}','Congruence compatibility','checking whether two residue prescriptions can coexist','For integers $m,n>0$ this compatibility condition is also sufficient; the period is $\\operatorname{lcm}(m,n)$.')], 'modular')
